/* ===== Prononciation interactive ===== */
const SpeechRec=window.SpeechRecognition||window.webkitSpeechRecognition;
let PRONREC=null;
const pronLang=id=>{const sb=sOf(WMAP[id].id),sid=sb.id;return sb.lang||(sid==='anglais'?'en':sid==='italien'?'it':null);};
const pronLocale=l=>window.MQAudio?MQAudio.recognitionLocale(l):(l==='en'?'en-GB':l==='it'?'it-IT':'fr-FR');
function pronClean(t){return String(t||'').replace(/\s*[/|]\s*/g,' ').replace(/[.…]/g,' ').replace(/\s+/g,' ').trim();}
function pronTargets(id){const lang=pronLang(id);if(!lang)return [];const c=COURS[id],ch=byId(id),box=document.createElement('div');let html='';
 if(ch&&ch.f)html+=(ch.f.ex||'')+(ch.f.l||[]).join(' ');
 if(c){html+=(c.parts||[]).map(x=>x.h||'').join(' ')+(c.ex?.s||[]).join(' ')+(c.retenir||[]).join(' ');}
 box.innerHTML=html;const raw=[...box.querySelectorAll(`[lang="${lang}"]`)].map(x=>pronClean(x.textContent)).filter(Boolean);
 const uniq=[];for(const x of raw){if(x.length<2||x.length>110||/[→=]/.test(x)||x.includes(' / '))continue;if(!uniq.some(y=>normLang(y,lang)===normLang(x,lang)))uniq.push(x);}
 const phrases=uniq.filter(x=>x.split(/\s+/).length>=2);const singles=uniq.filter(x=>x.split(/\s+/).length<2);return [...phrases,...singles].slice(0,3);}
function editDist(a,b){const A=[...a],B=[...b],d=Array(B.length+1).fill(0);for(let j=0;j<=B.length;j++)d[j]=j;for(let i=1;i<=A.length;i++){let prev=d[0];d[0]=i;for(let j=1;j<=B.length;j++){const old=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,prev+(A[i-1]===B[j-1]?0:1));prev=old;}}return d[B.length];}
function pronScore(got,want,lang){const a=normLang(got,lang),b=normLang(want,lang);if(!a||!b)return 0;if(a===b)return 100;const char=Math.max(0,1-editDist(a,b)/Math.max(a.length,b.length));const aw=a.split(' '),bw=b.split(' ');let hit=0;const tmp=[...aw];for(const w of bw){const i=tmp.indexOf(w);if(i>=0){hit++;tmp.splice(i,1);}}const words=hit/Math.max(1,bw.length);return Math.round((char*.58+words*.42)*100);}
function stopPron(){if(PRONREC){try{PRONREC.abort();}catch(e){}PRONREC=null;}}
function pronRenderState(msg='',kind='',score=null,heard=''){const st=$('#pronStatus'),m=$('#pronMeter i'),h=$('#pronHeard');if(st){st.className='pron-status '+kind;st.innerHTML=msg;}if(m&&score!=null)m.style.width=Math.max(0,Math.min(100,score))+'%';if(h)h.textContent=heard?`Reconnu : « ${heard} »`:'';}
function pronListen(){if(!L||!L.pronTargets?.length)return;const lang=pronLang(L.id),t=L.pronTargets[L.pronIndex]||L.pronTargets[0];ttsSpeak([{segs:[{l:lang,t}]}]);}
function pronStart(){if(!L||!L.pronTargets?.length)return;if(!SpeechRec){toast('La reconnaissance vocale n’est pas disponible dans ce navigateur.');return;}stopPron();ttsStop();const lang=pronLang(L.id),target=L.pronTargets[L.pronIndex];const r=new SpeechRec();PRONREC=r;r.lang=pronLocale(lang);r.interimResults=false;r.maxAlternatives=3;r.continuous=false;
 pronRenderState('🎙️ Je t’écoute… Dis la phrase clairement.','listening',0,'');
 const b=$('[data-a="pronsay"]');if(b){b.disabled=true;b.textContent='🎙️ Écoute…';}
 r.onresult=e=>{const alts=[...e.results[0]].map(x=>({t:x.transcript,s:pronScore(x.transcript,target,lang)})).sort((a,b)=>b.s-a.s),best=alts[0]||{t:'',s:0},ok=best.s>=74;PRONREC=null;
  if(ok){L.pronPassedCount=(L.pronPassedCount||0)+1;pronRenderState(`✅ Prononciation reconnue : <b>${best.s}%</b>`, 'good',best.s,best.t);sfx('ok');confetti(10);setTimeout(()=>{if(!L)return;if(L.pronIndex<L.pronTargets.length-1){L.pronIndex++;renderLesson();}else{L.pronPassed=true;renderLesson();}},850);}
  else{pronRenderState(`🔁 Encore une fois : <b>${best.s}%</b>. Écoute le modèle puis réessaie.`, 'bad',best.s,best.t);sfx('bad');if(b){b.disabled=false;b.textContent='🎤 Réessayer';}}};
 r.onerror=e=>{PRONREC=null;const txt=e.error==='not-allowed'?'Micro refusé : autorise le microphone dans le navigateur.':e.error==='no-speech'?'Je n’ai rien entendu. Réessaie en parlant un peu plus fort.':'Reconnaissance indisponible pour le moment. Réessaie.';pronRenderState('⚠️ '+txt,'bad',0,'');const bb=$('[data-a="pronsay"]');if(bb){bb.disabled=false;bb.textContent='🎤 Réessayer';}};
 r.onend=()=>{if(PRONREC===r)PRONREC=null;const bb=$('[data-a="pronsay"]');if(bb&&!L?.pronPassed){bb.disabled=false;bb.textContent='🎤 Dire la phrase';}};try{r.start();}catch(e){PRONREC=null;pronRenderState('⚠️ Impossible de démarrer le micro. Réessaie.','bad',0,'');}}

/* ===== Cours ===== */
const LESSON_QUIZ_N=6, LESSON_PASS=.70;
let L=null;
function coursesScreen(w){CUR='';L=null;const wd=WALL.find(x=>x.id===w)||WS()[0];S.subj=sOf(wd.id).id;const sc=SCH(S.subj),n=sc.filter(c=>S.lessons[c.id]).length,pct=sc.length?Math.round(n/sc.length*100):0;
 app.innerHTML=`${bar('📖 Cours')}<div class="card course-summary"><div class="csrow"><b>${n}/${sc.length} cours terminés</b><span>${pct} %</span></div><div class="prog"><i style="width:${pct}%"></i></div><p class="muted center">Programme officiel 2026-2027 · mode prof particulier : cours approfondis, méthode, exemples guidés, mini-défis et quiz de ${LESSON_QUIZ_N} questions. Validation à ${Math.ceil(LESSON_PASS*100)} % minimum.</p></div>
 <div class="tabs">${WS().map(x=>`<button class="tab ${x.id===wd.id?'on':''}" data-a="courses:${x.id}">${x.emoji} ${x.lvl}</button>`).join('')}</div>
 <div class="chaps" style="--wc:${wd.col}">${WCH[wd.id].map(c=>{const best=S.lessonScores[c.id]||0,done=!!S.lessons[c.id],st=done?`✅ Terminé · ${best}%`:best?`🟠 En cours · ${best}%`:'À découvrir';return `<button class="chap lsn" data-a="lesson:${c.id}"><span class="ci">${c.icon}</span><span class="cn">${c.name}</span><span class="cp ${done?'okc':'muted'}">${COURS[c.id]?.domain?`<b>${COURS[c.id].domain}</b><br>`:''}${st}<br>${masteryHTML(c.id)}${MQAdaptive.isDue(S,c.id)?' <span class="due">· à revoir</span>':''}${done?`<div class="fastline"><span class="muted small">Révision programmée ${MQAdaptive.dueInText(S,c.id)}</span></div>`:''}</span></button>`;}).join('')}</div></div>`;}
function tutorSubject(id){try{return sOf(WMAP[id].id).id}catch(e){return 'maths'}}
function tutorExtras(id,c){const sub=tutorSubject(id),ch=byId(id),name=ch?.name||'';
 const objectives=(c.objectives||c.retenir||[]).slice(0,4);
 const intro=`<div class="tutor-banner"><span class="tutor-avatar">${S.avatar}</span><div><b>Ton prof particulier est avec toi</b><span>On va avancer tranquillement, une idée à la fois. Tu n'as pas besoin de tout retenir d'un coup : comprends d'abord, puis entraîne-toi.</span></div></div>`;
 let know='',method='',why='',check='';
 if(sub==='maths'){
  know=`<div class="coach-grid"><div class="coach-card"><b>🧩 Ce que tu vas comprendre</b>${name}</div><div class="coach-card"><b>🔎 Le réflexe à avoir</b>Repère les données utiles, choisis la bonne règle, puis vérifie si ton résultat est logique.</div></div>`;
  method=`<div class="method-box"><div class="method-step"><span class="num">1</span><div><b>Je lis sans calculer</b><br>Je cherche ce que la question demande vraiment.</div></div><div class="method-step"><span class="num">2</span><div><b>Je choisis l'outil</b><br>Formule, propriété, opération ou représentation adaptée au chapitre.</div></div><div class="method-step"><span class="num">3</span><div><b>Je calcule proprement</b><br>Une ligne = une idée. Je garde les unités et les signes.</div></div><div class="method-step"><span class="num">4</span><div><b>Je contrôle</b><br>Ordre de grandeur, unité, signe : ma réponse est-elle possible ?</div></div></div>`;
  why=`<div class="whybox"><b>💡 Pourquoi ça marche ?</b><br>En maths, une règle n'est pas une formule magique : elle décrit une relation logique. Si tu peux expliquer avec tes mots ce que chaque nombre représente, tu es déjà en train de maîtriser le chapitre.</div>`;
  check=`<div class="checkpoint"><div class="q">🕵️ Mini-défi de prof</div>Avant de continuer, cache l'exemple avec ta main et explique à voix haute : « Quelle règle vais-je utiliser, et pourquoi ? » Si tu sais répondre, tu es prêt pour la suite.</div>`;
 }else if(sub==='francais'){
  know=`<div class="coach-grid"><div class="coach-card"><b>📖 D’abord le sens</b>En français, on ne collectionne pas des étiquettes : on observe comment les mots, les phrases et les textes fabriquent du sens.</div><div class="coach-card"><b>🔎 Puis la preuve</b>Une réponse solide contient toujours un indice précis : un mot, une construction, une citation courte ou un exemple.</div></div>`;
  method=`<div class="method-box"><div class="method-step"><span class="num">1</span><div><b>Je lis la consigne</b><br>Je repère le verbe demandé : identifier, expliquer, justifier, comparer, interpréter…</div></div><div class="method-step"><span class="num">2</span><div><b>J’observe</b><br>Je cherche les indices dans la phrase, le texte ou le document.</div></div><div class="method-step"><span class="num">3</span><div><b>Je raisonne</b><br>J’utilise la règle et j’explique le lien entre l’indice et ma réponse.</div></div><div class="method-step"><span class="num">4</span><div><b>Je relis</b><br>Je vérifie le sens, la syntaxe, les accords et l’orthographe.</div></div></div>`;
  why=`<div class="whybox"><b>💡 Le réflexe du bon lecteur</b><br>Quand tu repères une figure de style, un temps ou une fonction grammaticale, ne t’arrête pas au nom : demande-toi « <b>à quoi cela sert ici ?</b> ». C’est ce passage qui transforme une récitation en vraie compréhension.</div>`;
  check=`<div class="checkpoint"><div class="q">🧠 Défi prof particulier</div>Ferme mentalement la fiche et explique la notion en 20 secondes avec <b>ton propre exemple</b>. Puis donne une erreur fréquente à éviter. Si tu y arrives, la notion commence à être solide.</div>`;
 }else if(sub==='hg'){
  know=`<div class="coach-grid"><div class="coach-card"><b>🗺️ Où sommes-nous ?</b>Replace toujours le chapitre dans un lieu, une époque et un contexte.</div><div class="coach-card"><b>🧠 Question-clé</b>Qui agit ? Pourquoi ? Qu'est-ce qui change ? Quelles conséquences ?</div></div>`;
  method=`<div class="method-box"><div class="method-step"><span class="num">1</span><div><b>Je situe</b><br>Date, période, territoire.</div></div><div class="method-step"><span class="num">2</span><div><b>J'identifie les acteurs</b><br>Personnes, groupes, États, sociétés.</div></div><div class="method-step"><span class="num">3</span><div><b>Je relie causes et conséquences</b><br>Je ne récite pas : j'explique les liens.</div></div><div class="method-step"><span class="num">4</span><div><b>Je retiens 3 repères</b><br>Une date, un lieu, une idée essentielle.</div></div></div>`;
  why=`<div class="whybox"><b>💡 Le secret pour retenir</b><br>Transforme le cours en histoire : « avant → événement → après ». Le cerveau mémorise mieux une chaîne logique qu'une liste de dates isolées.</div>`;
  check=`<div class="checkpoint"><div class="q">🎙️ Raconte-le en 30 secondes</div>Explique le chapitre comme si tu le racontais à quelqu'un qui ne le connaît pas. Si tu arrives à dire le contexte, l'événement principal et une conséquence, c'est gagné.</div>`;
 }else if(sub==='emc'){
  know=`<div class="coach-grid"><div class="coach-card"><b>⚖️ La règle et la valeur</b>En EMC, distingue toujours ce qui relève d'un droit, d'une règle, d'une liberté, d'un devoir ou d'une valeur de la République.</div><div class="coach-card"><b>🗣️ Je justifie</b>Une bonne réponse ne dit pas seulement « oui » ou « non » : elle explique pourquoi avec un principe précis.</div></div>`;
  method=`<div class="method-box"><div class="method-step"><span class="num">1</span><div><b>Je comprends la situation</b><br>Qui est concerné ? Que se passe-t-il ?</div></div><div class="method-step"><span class="num">2</span><div><b>Je repère le principe</b><br>Droit, liberté, égalité, laïcité, solidarité, loi…</div></div><div class="method-step"><span class="num">3</span><div><b>Je confronte les points de vue</b><br>Je distingue faits, opinions et arguments.</div></div><div class="method-step"><span class="num">4</span><div><b>Je justifie</b><br>Je donne une réponse claire appuyée sur une règle ou une valeur.</div></div></div>`;
  why=`<div class="whybox"><b>💡 Le réflexe citoyen</b><br>Demande-toi : « Quelle liberté ou quel droit est en jeu ? Quelle règle permet de protéger chacun ? » Cela évite les réponses au simple ressenti.</div>`;
  check=`<div class="checkpoint"><div class="q">🗣️ Défends ton idée</div>Donne ton avis en une phrase, puis ajoute : « parce que… » et cite un droit, une règle ou une valeur qui justifie ta réponse.</div>`;
 }else{
  const lang=sub==='italien'?'italien':'anglais';
  know=`<div class="coach-grid"><div class="coach-card"><b>👂 D'abord le sens</b>Comprends la phrase entière avant de traduire mot à mot.</div><div class="coach-card"><b>🗣️ Puis la bouche</b>Lis, écoute et répète : une langue se mémorise aussi avec l'oreille et la voix.</div></div>`;
  method=`<div class="method-box"><div class="method-step"><span class="num">1</span><div><b>Je repère</b><br>Le sujet, le verbe et les mots importants.</div></div><div class="method-step"><span class="num">2</span><div><b>Je comprends</b><br>Je cherche le sens global en ${lang}, sans traduire chaque mot séparément.</div></div><div class="method-step"><span class="num">3</span><div><b>Je répète</b><br>Je prononce plusieurs fois avec le rythme de la phrase.</div></div><div class="method-step"><span class="num">4</span><div><b>Je réutilise</b><br>Je crée une nouvelle phrase avec la même structure.</div></div></div>`;
  why=`<div class="whybox"><b>💡 Astuce mémoire</b><br>Associe chaque nouveau mot à une image, un geste ou une situation. Une phrase vivante se retient mieux qu'une traduction isolée.</div>`;
  check=`<div class="checkpoint"><div class="q">🎭 Joue la scène</div>Imagine que tu es vraiment dans la situation du cours. Dis une phrase à voix haute, puis change un mot pour créer ta propre phrase.</div>`;
 }
 const goals=`<ul class="goal-list">${objectives.map(x=>`<li>${x}</li>`).join('')||'<li>Comprendre la notion et savoir l’utiliser seul.</li>'}</ul>`;
 const mv=MQAdaptive.mastery(S,id),ml=MQAdaptive.masteryLabel(mv),ra=MQAdaptive.recentAccuracy(S,id),due=MQAdaptive.isDue(S,id);
 const profile=`<div class="adaptive-card"><b>🧭 Ton parcours personnalisé</b><div class="adaptive-kpis"><div><b>${ml.e} ${mv}%</b><span>Maîtrise</span></div><div><b>${ra==null?'—':Math.round(ra*100)+'%'}</b><span>Réussite récente</span></div><div><b>${MQAdaptive.lessonDifficulty(S,id)}/3</b><span>Niveau de départ</span></div></div><p class="muted small">${mv===0?'Première découverte : on commence doucement.':due?'Cette notion revient aujourd’hui pour consolider ta mémoire.':mv>=85?'Tu maîtrises déjà bien : cherche surtout à expliquer et à transférer la méthode.':mv>=65?'La notion est acquise, mais quelques exercices vont la rendre automatique.':'On va renforcer les bases avant d’augmenter la difficulté.'}</p></div>`;
 const memory=`<div class="memory-map">${(c.retenir||[]).map((x,i)=>`<div><span>${['🟣','🟡','🟢'][i%3]}</span><b>${x}</b></div>`).join('')}</div>`;
 return {intro,goals,profile,know,method,why,check,memory};}
