// Les voix sont chargées (et rechargées sur « voiceschanged ») par le moteur audio (js/audio-engine.js).
function ttsBar(){if(!TTS.ok)return '';return `<div class="ttsbar"><button class="ttsb main" data-a="ttsplay" aria-label="Écouter cette étape">🔊 Écouter</button><button class="ttsb ${S.tts.auto?'on':''}" data-a="ttsauto" aria-pressed="${S.tts.auto}" title="Lire automatiquement chaque étape">Auto</button><button class="ttsb" data-a="ttsrate" title="Vitesse de lecture">${S.tts.rate<1?'🐢 Lent':'🐇 Normal'}</button></div>`;}
// V8.13 : choix de la voix délégué au moteur audio (jamais une voix d'une autre langue).
function ttsVoice(l='fr'){return window.MQAudio?MQAudio.pickVoice(l).voice:null;}
const SUPC='⁰¹²³⁴⁵⁶⁷⁸⁹',SUPM={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9','⁻':'moins ','ⁿ':'n'};
const ROM=r=>{const v={I:1,V:5,X:10};let n=0;for(let i=0;i<r.length;i++){const x=v[r[i]],y=v[r[i+1]]||0;n+=x<y?-x:x;}return n;};
// Préparation orale : règles propres aux maths (exposants, parallèles, f(x), noms de points), puis moteur audio (nombres, unités, monnaie, heures, fractions…).
function spoken(t){t=' '+String(t).replace(/[\u00a0\u202f]/g,' ')+' ';
 t=t.replace(new RegExp('([\\w)])²(?!['+SUPC+'])','g'),'$1 au carré ').replace(new RegExp('([\\w)])³(?!['+SUPC+'])','g'),'$1 au cube ');
 t=t.replace(new RegExp('[⁻ⁿ'+SUPC+']+','g'),m=>' puissance '+[...m].map(c=>SUPM[c]).join('')+' ');
 t=t.replace(/\/\//g,' parallèle à ').replace(/f\(([^)]*)\)/g,'f de $1');
 t=t.replace(/\b(?!SOH|CAH|TOA|ET\b|OU\b|BE\b|ING\b|ED\b|DO\b|DID\b|CAN\b|HAS\b|WAS\b|ARE\b|AM\b|IF\b|TO\b|ON\b|IN\b|AT\b|AN\b|ISC\b|CP\b|EPS\b|EMC\b|SVT\b|CDI\b|DNB\b)([A-Z])([A-Z])([A-Z])?\b/g,(m,a,b,c)=>` ${a} ${b} ${c||''} `);
 return window.MQAudio?MQAudio.prepareFR(t):t.replace(/\s+/g,' ').trim();}
const LANGF={fr:'fr-FR',en:'en-GB',it:'it-IT'};
function spokenFor(t){return String(t).replace(/_{2,}/g,' … ').replace(/\p{Extended_Pictographic}|\uFE0F|\u200D/gu,'').replace(/\s+/g,' ').trim();}
function segsOf(el){if(!el)return [];const root=(el.closest&&el.closest('[lang]'))?el.closest('[lang]').getAttribute('lang').slice(0,2):'fr',c=el.cloneNode(true);c.querySelectorAll('svg,kbd,button,input,.bav').forEach(x=>x.remove());
 c.querySelectorAll('.fr').forEach(f=>{const p=f.querySelectorAll('span');f.replaceWith(` ${p[0]?p[0].textContent:''} sur ${p[1]?p[1].textContent:''} `);});
 c.querySelectorAll('sup').forEach(x=>{const t=x.textContent;x.replaceWith(t==='2'?' au carré ':t==='3'?' au cube ':` puissance ${t} `);});
 if(el.tagName==='PRE')return [{l:'fr',t:spoken(c.textContent.split('\n').map(l=>l.replace(/─+/g,'').replace(/(\d)\s+(?=\d)/g,'$1').replace(/\s*,\s*(?=\d)/g,',').trim()).filter(Boolean).join('. '))}];
 if(el.tagName==='TR'){const k=[...c.children];k.forEach((td,i)=>{if(i<k.length-1&&td.textContent.trim())td.append(', ');});}
 const out=[];const push=(l,t)=>{const last=out[out.length-1];if(last&&(last.l===l||!/[\p{L}\p{N}]/u.test(t)))last.t+=t;else out.push({l,t});};
 const walk=(n,l)=>{if(n.nodeType===3){push(l,n.textContent);return;}if(n.nodeType!==1)return;const nl=n.getAttribute('lang')?n.getAttribute('lang').slice(0,2):l;n.childNodes.forEach(ch=>walk(ch,nl));};
 walk(c,c.getAttribute&&c.getAttribute('lang')?c.getAttribute('lang').slice(0,2):root);
 return out.map(x=>({l:x.l,t:x.l==='fr'?spoken(x.t):spokenFor(x.t)})).filter(x=>x.t&&/[\p{L}\p{N}]/u.test(x.t));}
function ttsSay(a,opt={}){if(!a||!TTS.ok)return;TTS.slowOnce=!!opt.slow;ttsSpeak([{segs:[{l:String(a.l||'fr').slice(0,2),t:a.t,type:a.k||'phrase',fresh:true}]}]);}
function ttsChunks(root){const out=[];let run=[];if(!root)return out;
 const flush=()=>{if(run.length&&run.map(n=>n.textContent).join('').trim()){const sp=document.createElement('span');sp.className='rdc';run[0].parentNode.insertBefore(sp,run[0]);run.forEach(n=>sp.appendChild(n));out.push(sp);}run=[];};
 [...root.childNodes].forEach(n=>{if(n.nodeType===3||(n.nodeType===1&&/^(B|I|SPAN|SUP|SMALL|EM|STRONG)$/.test(n.tagName))){run.push(n);return;}
  flush();if(n.nodeType!==1)return;const t=n.tagName.toUpperCase(),cl=n.classList;
  if(t==='BR'||t==='SVG'||t==='BUTTON'||t==='INPUT'||cl.contains('ans')||cl.contains('qbtns')||cl.contains('reread')||n.id==='fb')return;
  if(cl.contains('tw'))return n.querySelectorAll('tr').forEach(r=>out.push(r));
  if(t==='OL'||t==='UL')return n.querySelectorAll(':scope>li').forEach(li=>out.push(li));
  if(cl.contains('bubble'))return out.push(n.querySelector('div'));
  if(cl.contains('choices'))return n.querySelectorAll('.choice').forEach(x=>out.push(x));
  out.push(n);});
 flush();return out;}
function lessonChunks(){return [$('.lcard h2'),...ttsChunks($('.lcard .lbody'))];}
function ttsStop(){if(!TTS.ok)return;TTS.gen++;TTS.playing=false;TTS.q=[];try{if(window.MQAudio)MQAudio.stop();else speechSynthesis.cancel();}catch(e){}document.querySelectorAll('.reading').forEach(e=>e.classList.remove('reading'));ttsBtn();}
function ttsSpeak(els){if(!TTS.ok)return;ttsStop();TTS.q=els.filter(Boolean);TTS.i=0;TTS.playing=true;ttsBtn();ttsNext(TTS.gen);}
function ttsNext(g){if(g!==TTS.gen)return;document.querySelectorAll('.reading').forEach(e=>e.classList.remove('reading'));
 if(!TTS.playing||TTS.i>=TTS.q.length){TTS.playing=false;ttsBtn();return;}
 const it=TTS.q[TTS.i++],isEl=typeof Element!=='undefined'&&it instanceof Element;if(isEl&&!it.isConnected)return ttsNext(g);
 const segs=isEl?segsOf(it):(it.segs||[]);if(!segs.length)return ttsNext(g);
 if(isEl){it.classList.add('reading');try{it.scrollIntoView({block:'nearest',behavior:'smooth'});}catch(e){}}
 // V8.13 : lecture par le moteur audio (voix de la bonne langue, vitesse normale/lente, consignes plus lentes en CP-CE1).
 MQAudio.setPrefs((S.tts&&S.tts.voices)||{});const slow=S.tts.rate<1||TTS.slowOnce;TTS.slowOnce=false;
 // 21/10/2026 : ce bloc ET les suivants partent dans la même file du moteur (lecture continue, sans coupure entre blocs) ;
 // le surlignage suit le bloc réellement lu (onsegment).
 const items=[{el:isEl?it:null,segs}];while(TTS.i<TTS.q.length){const nx=TTS.q[TTS.i++],nEl=typeof Element!=='undefined'&&nx instanceof Element;if(nEl&&!nx.isConnected)continue;const ns=nEl?segsOf(nx):(nx.segs||[]);if(ns.length)items.push({el:nEl?nx:null,segs:ns});}
 const flat=[],owner=[];items.forEach((x,k)=>x.segs.forEach(sg=>{flat.push({t:sg.t,l:sg.l,type:sg.fresh?(sg.type||'phrase'):'raw'});owner.push(k);}));
 MQAudio.speak(flat,{slow,young:!!(window.MQPrimary&&MQPrimary.young(S.grade)),
  onsegment:i=>{if(g!==TTS.gen)return;const el=items[owner[i]]&&items[owner[i]].el;document.querySelectorAll('.reading').forEach(e=>{if(e!==el)e.classList.remove('reading');});if(el&&el.isConnected&&!el.classList.contains('reading')){el.classList.add('reading');try{el.scrollIntoView({block:'nearest',behavior:'smooth'});}catch(e){}}},
  onend:()=>ttsNext(g)});}
function ttsBtn(){document.querySelectorAll('[data-a="ttsplay"]').forEach(b=>{b.classList.toggle('on',TTS.playing);b.innerHTML=TTS.playing?'⏹️ Stop':'🔊 Écouter';});
 document.querySelectorAll('[data-a="ttsq"]').forEach(b=>{b.classList.toggle('on',TTS.playing);b.textContent=TTS.playing?'⏹️':'🔊';});}

/* ===== Diagnostic des voix (réglages parent) ===== */
const VOICE_SAMPLES={fr:'Bonjour ! Il est 8 h 30 et le cahier coûte 3,50 €.',en:'Hello! My name is Tom and I live in London.',it:'Ciao! Mi chiamo Giulia e abito a Roma.'};
function voicePrefsFromForm(){const o={};['fr','en','it'].forEach(l=>{const v=$('#vsel_'+l)?.value;if(v)o[l]=v;});return o;}
function voiceDiagHTML(){if(!window.MQAudio||!MQAudio.supported())return '<p class="muted">La synthèse vocale n’est pas disponible dans ce navigateur.</p>';MQAudio.setPrefs(S.tts.voices||{});const d=MQAudio.diagnostics(),N={fr:'Français (fr-FR)',en:'Anglais (en-GB)',it:'Italien (it-IT)'},ST={exact:'voix de la bonne région',language:'voix de la même langue (autre région)',preferred:'voix choisie',['engine-default']:'choisie par le navigateur',unavailable:'aucune voix installée'};
 return `<div class="vdiag">${['fr','en','it'].map(l=>{const c=d.chosen[l],vs=MQAudio.voicesFor(l);return `<div class="frow"><span class="grow"><b>${N[l]}</b><br><small class="muted">${c.voice?esc(c.voice)+' · '+esc(c.voiceLang):'—'} · ${ST[c.status]||c.status}</small></span>${vs.length?`<select id="vsel_${l}" class="fld"><option value="">Automatique</option>${vs.map(v=>`<option value="${esc(v.voiceURI)}" ${S.tts.voices&&S.tts.voices[l]===v.voiceURI?'selected':''}>${esc(v.name)} (${esc(v.lang)})</option>`).join('')}</select>`:''}<button class="btn sm2" data-a="voicetest:${l}" ${c.status==='unavailable'?'disabled':''}>▶️</button></div>`;}).join('')}<button class="btn primary wide" data-a="voicesave">💾 Enregistrer les voix</button><details class="vtip"><summary>🎙️ La voix est trop robotique ? Installer une voix naturelle (gratuit)</summary><ul class="small"><li><b>Windows</b> : ouvrez Finot Académie dans <b>Microsoft Edge</b>, qui propose des voix « Natural » très réalistes (Internet nécessaire), ou bien Paramètres → Heure et langue → Voix → ajoutez une voix française « Natural ».</li><li><b>iPhone / iPad</b> (voix la plus naturelle et la plus douce) : Réglages → Accessibilité → Contenu énoncé → Voix → Français (France) → <b>Audrey</b> → téléchargez <b>« Audrey (Premium) »</b>, ou à défaut « Audrey (Améliorée) ». Fermez puis rouvrez Finot Académie : elle est choisie automatiquement.</li><li><b>Mac</b> : Réglages Système → Accessibilité → Contenu énoncé → Voix du système → Gérer les voix → voix française « premium ».</li><li><b>Android</b> : Paramètres → Synthèse vocale → moteur Google → installez les données vocales françaises en « haute qualité ».</li></ul><p class="muted small">Revenez ensuite ici : Finot Académie choisit automatiquement la voix la plus naturelle, ou vous la choisissez dans la liste.</p></details>
 <details><summary>${d.count} voix détectée(s) sur l’appareil</summary><table class="ptable"><tr><th>Nom</th><th>Langue</th><th>Moteur</th></tr>${d.voices.map(v=>`<tr><td>${esc(v.name)}${v.default?' ⭐':''}</td><td>${esc(v.locale)}</td><td>${esc(v.engine)}</td></tr>`).join('')}</table></details>
 <p class="muted small">Reconnaissance vocale : ${d.recognition?'disponible (fr-FR, en-GB, it-IT selon l’exercice)':'non disponible dans ce navigateur'}.</p></div>`;}
if(window.MQAudio)MQAudio.onUnavailable=l=>toast(`🔇 Aucune voix ${({fr:'française',en:'anglaise',it:'italienne'})[l]||l} sur cet appareil : le texte reste affiché.`);

/* ===== Brouillon ===== */
const PAD={open:false,mode:'draw',tool:'pen',color:'#1f2937',strokes:[],cv:null,ctx:null};
function padInit(){if($('#pad'))return;const d=document.createElement('aside');d.id='pad';d.setAttribute('aria-label','Brouillon');
 d.innerHTML=`<div class="padh"><b>✏️ Brouillon</b><div class="padtabs"><button data-a="padmode:draw" class="on">Dessin</button><button data-a="padmode:text">Clavier</button></div><button class="btn ghost sm" data-a="padclose" aria-label="Fermer le brouillon">✕</button></div>
 <div class="padq" id="padq"></div>
 <div class="padtools" id="padtools">${[['#1f2937','Crayon noir'],['#1d4ed8','Crayon bleu'],['#dc2626','Crayon rouge'],['#16a34a','Crayon vert']].map(([c,l],i)=>`<button class="pcol ${i?'':'on'}" data-a="padcol:${c}" style="--pc:${c}" aria-label="${l}"></button>`).join('')}
  <button class="ptool" data-a="padtool:erase" aria-label="Gomme">🧽</button><button class="ptool" data-a="padundo" aria-label="Annuler le dernier trait">↶</button><button class="ptool" data-a="padclear" aria-label="Tout effacer">🗑️</button></div>
 <div class="padarea"><div class="padwrap" id="padwrap"><canvas id="padcv"></canvas></div><textarea id="padtx" class="padtx" spellcheck="false" placeholder="Pose tes calculs ici (police à chasse fixe : les chiffres s’alignent en colonnes)"></textarea></div>`;
 document.body.appendChild(d);const cv=$('#padcv');PAD.cv=cv;PAD.ctx=cv.getContext('2d');let cur=null;
 const pt=e=>{const r=cv.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];};
 cv.addEventListener('pointerdown',e=>{e.preventDefault();cv.setPointerCapture(e.pointerId);const er=PAD.tool==='erase';cur={c:PAD.color,w:er?24:e.pointerType==='pen'?2.5:3,er,p:[pt(e)]};PAD.strokes.push(cur);strokeSeg(cur,0);});
 cv.addEventListener('pointermove',e=>{if(!cur)return;const evs=e.getCoalescedEvents?e.getCoalescedEvents():[e];evs.forEach(ev=>{cur.p.push(pt(ev));strokeSeg(cur,cur.p.length-2);});});
 const up=()=>{cur=null;};cv.addEventListener('pointerup',up);cv.addEventListener('pointercancel',up);
 if(window.ResizeObserver)new ResizeObserver(padFit).observe($('#padwrap'));window.addEventListener('resize',padFit);}
function strokeSeg(s,i){const c=PAD.ctx;c.globalCompositeOperation=s.er?'destination-out':'source-over';c.strokeStyle=s.c;c.lineWidth=s.w;c.lineCap='round';c.lineJoin='round';c.beginPath();const a=s.p[Math.max(0,i)],b=s.p[Math.min(s.p.length-1,i+1)]||a;c.moveTo(a[0],a[1]);c.lineTo(b[0]+(a===b?.1:0),b[1]);c.stroke();}
function padDraw(){const c=PAD.ctx;if(!c)return;c.save();c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,PAD.cv.width,PAD.cv.height);c.restore();PAD.strokes.forEach(s=>{for(let i=0;i<s.p.length;i++)strokeSeg(s,i);});}
function padFit(){const w=$('#padwrap');if(!w||!PAD.open)return;const r=w.getBoundingClientRect(),dpr=window.devicePixelRatio||1;if(!r.width)return;PAD.cv.width=Math.round(r.width*dpr);PAD.cv.height=Math.round(r.height*dpr);PAD.cv.style.width=r.width+'px';PAD.cv.style.height=r.height+'px';PAD.ctx.setTransform(dpr,0,0,dpr,0,0);padDraw();}
function padReset(qhtml){padInit();PAD.strokes=[];padDraw();$('#padtx').value='';$('#padq').innerHTML=String(qhtml||'').replace(/<svg[\s\S]*?<\/svg>/g,'');}
function padOpen(){padInit();PAD.open=true;$('#pad').classList.add('open');document.body.classList.add('padopen');padMode(PAD.mode);requestAnimationFrame(padFit);}
function padClose(){PAD.open=false;const p=$('#pad');if(p)p.classList.remove('open');document.body.classList.remove('padopen');}
function padMode(m){PAD.mode=m;const d=$('#pad');d.classList.toggle('txt',m==='text');d.querySelectorAll('.padtabs button').forEach(b=>b.classList.toggle('on',b.dataset.a==='padmode:'+m));if(m==='text')$('#padtx').focus();else requestAnimationFrame(padFit);}

function gradeChapters(subjectId=S.subj){const a=SCH(subjectId),g=a.filter(c=>WMAP[c.id]?.lvl===S.grade);return g.length?g:a;}
function smartWeak(subjectId=S.subj,limit=5){return MQAdaptive.weakChapters(S,SCH(subjectId),WMAP,S.grade,limit);}
function smartPlanHTML(){const arr=smartWeak(S.subj,3);if(!arr.length)return '<div class="card"><b>🌱 Commence par un premier chapitre</b><div class="muted small">L’application adaptera ensuite les révisions à tes résultats.</div></div>';return `<div class="today-plan">${arr.map((x,i)=>`<button class="row" data-a="chap:${x.c.id}"><span><b>${i+1}. ${x.c.icon} ${x.c.name}</b><small class="muted">${x.acc==null?'Nouveau chapitre':Math.round(x.acc*100)+' % récent'} · maîtrise ${x.mastery}% ${x.due?'· 🔁 à revoir':''}</small></span><span class="go">Travailler</span></button>`).join('')}</div>`;}
function smartReviewScreen(){CUR='smartreview';const arr=smartWeak(S.subj,6),err=Object.values(S.mistakes||{}).reduce((n,a)=>n+(Array.isArray(a)?a.filter(x=>!x.seen).length:0),0);app.innerHTML=`${bar('🧠 Révision intelligente')}<div class="adaptive-card"><div style="display:flex;gap:12px;align-items:flex-start;"><img src="${FINOT_IMG.revision}" alt="" aria-hidden="true" class="finot-live" style="width:48px;height:48px;border-radius:50%;object-fit:cover;object-position:50% 35%;flex:0 0 auto;"><div><b>Ton entraînement s’adapte à toi</b><p class="muted small">Priorité aux notions dues, aux erreurs récentes et aux chapitres fragiles. La difficulté varie de 1 à 3 pendant l’exercice, sans attendre la fin de la mission.</p></div></div><div class="adaptive-kpis"><div><b>${S.adaptive?.answers||0}</b><span>réponses analysées</span></div><div><b>${S.adaptive?.adaptations||0}</b><span>ajustements</span></div><div><b>${err}</b><span>erreurs à revoir</span></div></div></div><button class="btn wide" data-a="mistakes">📒 Ouvrir mon carnet d’erreurs</button><h2 class="sec">Priorités du moment</h2>${arr.length?arr.map((x,i)=>{const ml=MQAdaptive.masteryLabel(x.mastery);return `<div class="card focusline"><span style="font-size:28px">${x.c.icon}</span><div class="grow"><b>${x.c.name}</b><div class="muted small">${ml.e} ${ml.t} ${x.mastery}% · ${x.acc==null?'peu de données':Math.round(x.acc*100)+' % récent'} · niveau ${MQAdaptive.difficulty(S,x.c.id)}/3 ${x.due?'· <span class="due">révision due</span>':''}</div></div><button class="btn primary sm2" data-a="reviewstart:${x.c.id}">8 questions</button></div>`}).join(''):'<div class="card">Aucune faiblesse détectée pour le moment. Continue quelques missions pour personnaliser les révisions.</div>'}<button class="btn ghost wide" data-a="home">← Accueil</button>`;}
function mistakesScreen(){CUR='mistakes';const rows=[];Object.entries(S.mistakes||{}).forEach(([id,a])=>{const c=CHMAP[id];if(!c||!Array.isArray(a))return;a.filter(x=>!x.seen).slice(0,4).forEach(x=>rows.push({id,c,x}));});rows.sort((a,b)=>b.x.at-a.x.at);app.innerHTML=`${bar('📒 Carnet d’erreurs')}<div class="card" style="display:flex;gap:12px;align-items:flex-start;"><img src="${FINOT_IMG.carnet}" alt="" aria-hidden="true" class="finot-live" style="width:48px;height:48px;border-radius:50%;object-fit:cover;object-position:50% 35%;flex:0 0 auto;"><div><b>Une erreur n’est pas perdue</b><p class="muted small">Finot Académie conserve les erreurs récentes pour te faire revoir exactement ce qui a bloqué. Une bonne réponse ultérieure marque progressivement l’erreur comme retravaillée.</p></div></div>${rows.length?rows.slice(0,20).map(r=>`<div class="card error-card"><span class="errico">${r.c.icon}</span><div><b>${r.c.name}</b><p>${esc(r.x.q)}</p><p class="muted small">Réponse attendue : <b>${esc(r.x.answer)}</b>${r.x.expl?' · '+esc(r.x.expl):''}</p><button class="btn sm2" data-a="reviewstart:${r.id}">🔁 Retravailler ce chapitre</button></div></div>`).join(''):'<div class="card center">✅ Aucune erreur en attente. Continue ainsi.</div>'}<button class="btn ghost wide" data-a="smartreview">← Révision intelligente</button>`;}
